-- 2026-11-07n: MP Background timelines for batch 22, 25 more current MPs (owner's approval, "yes", 7 Nov 2026).
-- Sets background_timeline (215 entries, copied exactly from "background/background-batch22-draft.json", which is not committed) and
-- background_last_checked = 2026-11-07 for member_ids 5120, 5121, 5122, 5124, 5125, 5126, 5127, 5128, 5130, 5131, 5132, 5136, 5138, 5139, 5140, 5144, 5146, 5149, 5150, 5152, 5153, 5155, 5157, 5159, 5160,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Cowork researched every entry
-- and opened every source on 7 Nov 2026. Sources: politics.co.uk, the Register of Members' Financial Interests of 11 Nov 2024,
-- Wikipedia, Hansard, LabourList, Island Echo, Altrincham Today, InterTradeIreland, Gedling Borough Council, and the MPs' own websites.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-11-07n-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 471 existing timelines are unchanged (md5);
-- MPs with a timeline go from 471 to 496; each array equals the file exactly; 6281 entries in all afterwards.
-- Undo: 2026-11-07n-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN READ WRITE;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (5120, 5121, 5122, 5124, 5125, 5126, 5127, 5128, 5130, 5131, 5132, 5136, 5138, 5139, 5140, 5144, 5146, 5149, 5150, 5152, 5153, 5155, 5157, 5159, 5160)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (5120, 5121, 5122, 5124, 5125, 5126, 5127, 5128, 5130, 5131, 5132, 5136, 5138, 5139, 5140, 5144, 5146, 5149, 5150, 5152, 5153, 5155, 5157, 5159, 5160) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 471 THEN RAISE EXCEPTION 'expected 471 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
